276	              ),
277	              ...(instanceOrOptions as FastifyServerOptions)?.routerOptions,
278	              constraints: {
279	                version: this.versionConstraint as any,
280	              },
281	            },
282	          });
283	
284	    this.setInstance(instance);
285	
286	    if ((instanceOrOptions as FastifyAdapterBaseOptions)?.skipMiddie) {
287	      this.isMiddieRegistered = true;
288	    }
289	
290	    // The option doubles as a native Fastify server option, where it is
291	    // forwarded untouched; the adapter only records it here so that
292	    // "initHttpServer" installs its own (Express-compatible) request gate
293	    // even when no application-level "return503OnClosing" option is set.
294	    this.return503OnClosing =
295	      !!(instanceOrOptions as FastifyAdapterBaseOptions)?.return503OnClosing;
296	
297	    this.instance.addHook('onRequest', (request, reply, done) => {
298	      if (this.onRequestHook) {
299	        this.onRequestHook(request as TRequest, reply as TReply, done);
300	      } else {
301	        done();
302	      }
303	    });
304	
305	    this.instance.addHook('onResponse', (request, reply, done) => {
306	      if (this.onResponseHook) {
307	        this.onResponseHook(request as TRequest, reply as TReply, done);
308	      } else {
309	        done();
310	      }
311	    });
312	  }
