459	  public reply(
460	    response: TRawResponse | TReply,
461	    body: any,
462	    statusCode?: number,
463	  ) {
464	    const fastifyReply: TReply = this.isNativeResponse(response)
465	      ? new Reply(
466	          response,
467	          {
468	            [kRouteContext]: {
469	              preSerialization: null,
470	              preValidation: [],
471	              preHandler: [],
472	              onSend: [],
473	              onError: [],
474	            },
475	          },
476	          {},
477	        )
478	      : response;
479	
480	    if (!isNil(statusCode)) {
481	      fastifyReply.status(statusCode);
482	    }
483	    if (body instanceof StreamableFile) {
484	      const streamHeaders = body.getHeaders();
485	      if (
486	        fastifyReply.getHeader('Content-Type') === undefined &&
487	        streamHeaders.type !== undefined
488	      ) {
489	        fastifyReply.header('Content-Type', streamHeaders.type);
490	      }
491	      if (
492	        fastifyReply.getHeader('Content-Disposition') === undefined &&
493	        streamHeaders.disposition !== undefined
494	      ) {
495	        fastifyReply.header('Content-Disposition', streamHeaders.disposition);
496	      }
497	      if (
498	        fastifyReply.getHeader('Content-Length') === undefined &&
499	        streamHeaders.length !== undefined
500	      ) {
501	        fastifyReply.header('Content-Length', streamHeaders.length);
502	      }
503	      body = body.getStream();
504	    }
505	    if (
506	      fastifyReply.getHeader('Content-Type') !== undefined &&
507	      fastifyReply.getHeader('Content-Type') !== 'application/json' &&
508	      body?.statusCode >= HttpStatus.BAD_REQUEST
509	    ) {
510	      Logger.warn(
511	        "Content-Type doesn't match Reply body, you might need a custom ExceptionFilter for non-JSON responses",
512	        FastifyAdapter.name,
513	      );
514	      fastifyReply.header('Content-Type', 'application/json');
515	    }
516	    return fastifyReply.send(body);
517	  }
