862	  /**
863	   * Installs a request gate in front of Fastify's routing so that, once the
864	   * shutdown has started, new requests are rejected with
865	   * "503 Service Unavailable" before they can enter the Nest pipeline
866	   * (middleware, guards, pipes, interceptors, handlers), while requests
867	   * that were already accepted run to completion.
868	   *
869	   * The gate has two layers:
870	   *
871	   * - a wrapper around the server's "request" listener, which rejects every
872	   *   request whose headers arrive after the shutdown started — including
873	   *   requests pipelined on an existing keep-alive connection. The listener
874	   *   is wrapped instead of using a Fastify "onRequest" hook because
875	   *   Fastify's own "return503OnClosing" fast path (enabled by default)
876	   *   runs before any hook and answers with a JSON body, which would not
877	   *   match the Express-compatible contract (a plain "Service Unavailable"
878	   *   body and a "Connection: close" header);
879	   * - a "preHandler" hook, which covers requests that were accepted by the
880	   *   first layer while the application was still running but have not
881	   *   reached a route handler yet when the shutdown starts — most notably
882	   *   requests whose body is still streaming in. Fastify runs "preHandler"
883	   *   hooks after the request body has been fully received and right before
884	   *   the route handler (where the Nest pipeline begins), so a late
885	   *   rejection here still happens before any guard, pipe, interceptor or
886	   *   controller runs and cannot trigger business side effects.
887	   */
888	  private installClosingRequestGate() {
889	    const server = this.httpServer as unknown as http.Server;
890	    const routing = this.instance.routing;
891	    server.removeListener('request', routing);
892	    server.on('request', (req, res) => {
893	      if (!this.isShuttingDown) {
894	        routing(req as unknown as TRawRequest, res as unknown as TRawResponse);
895	        return;
896	      }
897	      if (req.httpVersionMajor !== 2) {
898	        res.setHeader('Connection', 'close');
899	      }
900	      res.writeHead(HttpStatus.SERVICE_UNAVAILABLE, {
901	        'Content-Type': 'text/plain',
902	      });
903	      res.end('Service Unavailable');
904	    });
905	
906	    this.instance.addHook('preHandler', (request, reply, done) => {
907	      if (!this.isShuttingDown) {
908	        done();
909	        return;
910	      }
911	      if (request.raw.httpVersionMajor !== 2) {
912	        reply.header('Connection', 'close');
913	      }
914	      // Short-circuit the lifecycle without calling "done()".
915	      reply
916	        .code(HttpStatus.SERVICE_UNAVAILABLE)
917	        .header('Content-Type', 'text/plain')
918	        .send('Service Unavailable');
919	    });
920	  }
