1101	
1102	  private removeDuplicateSlashes(path: string) {
1103	    const REMOVE_DUPLICATE_SLASHES_REGEXP = /\/\/+/g;
1104	    return path.indexOf('//') !== -1
1105	      ? path.replace(REMOVE_DUPLICATE_SLASHES_REGEXP, '/')
1106	      : path;
1107	  }
1108	
1109	  private trimLastSlash(path: string) {
1110	    if (path.length > 1 && path.charCodeAt(path.length - 1) === 47) {
1111	      return path.slice(0, -1);
1112	    }
1113	    return path;
1114	  }
